// 判断商品是否为包包类
function isHandbag(product) {
  const slug = (product.slug || '').toLowerCase();
  const nameCn = (product.nameCn || '').toLowerCase();
  
  // 检查 slug 是否包含非包包关键词
  for (const keyword of NON_BAG_KEYWORDS) {
    if (slug.includes(keyword)) {
      return false;
    }
  }
  
  return true;
}

// 将数据分成多个批次
function splitIntoParts(arr, size) {
  const parts = [];
  for (let i = 0; i < arr.length; i += size) {
    parts.push(arr.slice(i, i + size));
  }
  return parts;
}

// 云函数入口
// event 参数:
//   action: 'all' | 'clear-only' | 'import-part' | 'import-data'
//   part: 导入第几批（0, 1, 2, 3）
//   totalParts: 总批次数（用于最后一批）
//   products: 外部传入的商品数据（import-data 模式）
//   priceStocks: 外部传入的价格库存数据（import-data 模式）
exports.main = async (event = {}) => {
  const action = event.action || 'all';

  // 外部数据模式：直接使用传入的数据
  if (action === 'import-data') {
    const products = event.products || [];
    const priceStocks = event.priceStocks || [];
    const clear = event.clear !== false; // 默认先清空

    const result = {
      action: 'import-data',
      receivedProducts: products.length,
      receivedPriceStocks: priceStocks.length,
      clear: null,
      products: null,
      priceStocks: null
    };

    if (clear) {
      result.clear = {
        products: await clearCollection('products'),
        price_stock: await clearCollection('price_stock')
      };
    }

    // slug 去重
    const slugMap = {};
    for (const p of products) {
      const key = p.slug || p.productId || '';
      if (!key) continue;
      if (!slugMap[key]) {
        slugMap[key] = p;
      } else if (p.mainImage && !slugMap[key].mainImage) {
        slugMap[key] = p;
      }
    }
    const dedupedProducts = Object.values(slugMap);
    const dedupedIds = new Set(dedupedProducts.map(p => p.productId));
    const dedupedPS = priceStocks.filter(ps => dedupedIds.has(ps.productId));

    result.dedupedProducts = dedupedProducts.length;
    result.dedupedPriceStocks = dedupedPS.length;

    // 分批写入
    const PRODUCT_PART_SIZE = 30;
    for (let i = 0; i < dedupedProducts.length; i += PRODUCT_PART_SIZE) {
      const chunk = dedupedProducts.slice(i, i + PRODUCT_PART_SIZE);
      const toInsert = chunk.map(p => ({ ...p, createTime: db.serverDate() }));
      await batchInsert('products', toInsert);
    }

    const PS_PART_SIZE = 50;
    for (let i = 0; i < dedupedPS.length; i += PS_PART_SIZE) {
      const chunk = dedupedPS.slice(i, i + PS_PART_SIZE);
      const toInsert = chunk.map(ps => ({ ...ps, priceUpdateTime: db.serverDate() }));
      await batchInsert('price_stock', toInsert);
    }

    result.products = { inserted: dedupedProducts.length };
    result.priceStocks = { inserted: dedupedPS.length };

    return result;
  }

  // 过滤：只导入包包类商品，通过 slug 黑名单排除非包包类
  const HANDCBAG_PRODUCTS = PRODUCTS.filter(isHandbag);
  
  // 按 slug 去重：同一 slug 只保留一个，优先保留有图片的
  const slugMap = {};
  for (const p of HANDCBAG_PRODUCTS) {
    const key = p.slug || p.productId || '';
    if (!key) continue;
    if (!slugMap[key]) {
      slugMap[key] = p;
    } else if (p.mainImage && !slugMap[key].mainImage) {
      slugMap[key] = p;
    }
  }
  const FILTERED_PRODUCTS = Object.values(slugMap);
  const FILTERED_PRODUCT_IDS = new Set(FILTERED_PRODUCTS.map(p => p.productId));
  const FILTERED_PRICE_STOCKS = PRICE_STOCKS.filter(ps => FILTERED_PRODUCT_IDS.has(ps.productId));
  
  const stats = {
    action,
    rawCount: PRODUCTS.length,
    handbagCount: HANDCBAG_PRODUCTS.length,
    dedupedCount: FILTERED_PRODUCTS.length,
    nonHandbagFiltered: PRODUCTS.length - HANDCBAG_PRODUCTS.length,
    duplicateFiltered: HANDCBAG_PRODUCTS.length - FILTERED_PRODUCTS.length,
    priceStockCount: FILTERED_PRICE_STOCKS.length,
    clear: null,
    products: null,
    priceStocks: null
  };

  // 清空旧数据
  if (action === 'all' || action === 'clear-only') {
    stats.clear = {
      products: await clearCollection('products'),
      price_stock: await clearCollection('price_stock')
    };
  }

  // 仅清空
  if (action === 'clear-only') {
    return stats;
  }

  // 分批导入模式
  if (action === 'import-part') {
    const part = event.part || 0;
    const totalParts = Math.ceil(FILTERED_PRODUCTS.length / PART_SIZE);
    
    // 计算当前批次的数据范围
    const start = part * PART_SIZE;
    const end = start + PART_SIZE;
    const partProducts = FILTERED_PRODUCTS.slice(start, end);
    const partPriceStocks = FILTERED_PRICE_STOCKS.filter(ps => 
      partProducts.some(p => p.productId === ps.productId)
    );

    // 写入当前批次的商品
    const productsToInsert = partProducts.map(p => ({
      ...p,
      createTime: db.serverDate()
    }));
    const productResult = await batchInsert('products', productsToInsert);

    // 写入当前批次的价格库存
    const priceStocksToInsert = partPriceStocks.map(ps => ({
      ...ps,
      priceUpdateTime: db.serverDate()
    }));
    const priceStockResult = await batchInsert('price_stock', priceStocksToInsert);

    return {
      action: 'import-part',
      part,
      totalParts,
      productRange: `${start}-${end}`,
      products: productResult,
      priceStocks: priceStockResult
    };
  }

  // 一次性全量导入（内部自动分批，避免超时）
  // 商品分批写入
  let productInserted = 0;
  const PRODUCT_BATCH = 20;
  for (let i = 0; i < FILTERED_PRODUCTS.length; i += PRODUCT_BATCH) {
    const chunk = FILTERED_PRODUCTS.slice(i, i + PRODUCT_BATCH);
    const toInsert = chunk.map(p => ({ ...p, createTime: db.serverDate() }));
    const result = await batchInsert('products', toInsert);
    productInserted += (result && result.added) || chunk.length;
  }

  // 价格库存分批写入
  let psInserted = 0;
  const PS_BATCH = 30;
  for (let i = 0; i < FILTERED_PRICE_STOCKS.length; i += PS_BATCH) {
    const chunk = FILTERED_PRICE_STOCKS.slice(i, i + PS_BATCH);
    const toInsert = chunk.map(ps => ({ ...ps, priceUpdateTime: db.serverDate() }));
    const result = await batchInsert('price_stock', toInsert);
    psInserted += (result && result.added) || chunk.length;
  }

  stats.products = { inserted: productInserted };
  stats.priceStocks = { inserted: psInserted };

  return stats;
};
